forall X -> X null() asm "PUSHNULL";
(cell, cell) duplicate_cell(cell x) impure { return (x, x); }
(slice, slice) duplicate_slice(slice x) impure { return (x, x); }
(int, slice) ones(slice s) impure asm "LDONES";
(int, slice) zeroes(slice s) impure asm "LDZEROES";
(int, slice) same(slice s, int bit) impure asm "LDSAME";
cell empty() asm "NEWC" "ENDC";
slice parse(cell c) asm "CTOS";
() recv_internal() { }
(cell, cell) cells(int flag) method_id(100001) {
 cell c = empty();
 if (flag) { return duplicate_cell(c); }
 return duplicate_cell(null());
}

(slice, slice) slices(cell c) method_id(100002) { return duplicate_slice(parse(c)); }
(int, slice) leading_ones(slice s) method_id(100003) { return ones(s); }
(int, slice) leading_zeroes(slice s) method_id(100004) { return zeroes(s); }
(int, slice) leading_same(slice s, int bit) method_id(100005) { return same(s, bit); }
(cell, cell) loop_cells(int n) method_id(100006) {
 cell c = empty();
 cell d = c;
 repeat(n) { (c, d) = duplicate_cell(c); }
 return (c,d);
}
